export const PROVED: Registry = Object.fromEntries(PROOFS.map(p => [p.theory, Object.fromEntries(p.theorems.map(t => [t.theorem, t]))]));
/** one theorem, or nothing - and never a throw */
export const proved = (of: Registry, theory: string, theorem: string): Proved | undefined => of[theory]?.[theorem];
/** which theories have an answer to a question */
export const theories = (of: Registry, theorem: string): string[] => Object.keys(of).filter(t => of[t][theorem]);
/** every question a theory answers */
export const asked = (of: Registry, theory: string): string[] => Object.keys(of[theory] ?? {});
